/**
 * GDD §9.2 — Power Points & member roster.
 *
 *   PowerPoints = unitPower + territoryPower
 *   unitPower      = Σ(unit cost equivalents commanded)
 *   territoryPower = Σ(hourly resource yield of hexes owned) × GUILD.powerYieldK
 *
 * Both halves stay separately visible everywhere: the roster reads them as
 * "power from the units they command" and "power from the ground they hold".
 * Power is *descriptive only* — it drives no mechanic. It exists so leaders can
 * see who is strong where and route resources by hand (GDD §8: "power
 * distribution is emergent, not mechanical").
 *
 * PURE: no DOM, no Three.js.
 */
import { ECONOMY, GUILD } from '../../config/balance';
import { UNITS } from '../../config/units';
import type {
  ArmyId,
  Cost,
  GameState,
  GuildId,
  GuildRole,
  Hex,
  HexId,
  PlayerId,
  PowerBreakdown,
  UnitType,
} from '../types';
import { roleOf } from './permissions';

/**
 * Mineral-equivalent value of one unit of Gas.
 *
 * Unit costs are two-dimensional (minerals + gas) but a Power Point is one
 * number, so the two currencies need an exchange rate. Rather than invent a
 * balance knob, it is DERIVED from ECONOMY: a commander may bank
 * `ECONOMY.capMinerals` minerals but only `ECONOMY.capGas` gas, so the design
 * has already declared gas to be `capMinerals / capGas` times as scarce. With
 * the shipped caps (12 000 / 1 200) that is exactly 10 minerals per gas.
 *
 * Because it is derived, retuning the caps in src/config retunes power scoring
 * automatically — there is no second number to keep in sync.
 */
export const GAS_MINERAL_EQUIV: number = ECONOMY.capMinerals / ECONOMY.capGas;

/** Collapse a mixed Cost into a single mineral-equivalent scalar. */
export function mineralEquivalent(cost: Cost): number {
  return cost.m + cost.g * GAS_MINERAL_EQUIV;
}

/** Mineral-equivalent build cost of one unit of `type`. */
export function unitMineralValue(type: UnitType): number {
  return mineralEquivalent(UNITS[type].cost);
}

/**
 * Hourly yield of a single controlled hex (GDD §4).
 * Terrain multiplier × per-hex base, plus the level-2+ fortification bonus.
 */
export function hexYieldPerHour(hex: Hex): Cost {
  const fortBonus = 1 + ECONOMY.fortYieldBonus[hex.fortLevel];
  const m = ECONOMY.mineralsPerHex * ECONOMY.yieldByTerrain[hex.terrain] * fortBonus;
  const g = hex.gas ? ECONOMY.gasPerGasHex * fortBonus : 0;
  return { m, g };
}

const zeroPower = (): PowerBreakdown => ({
  unitPower: 0,
  territoryPower: 0,
  total: 0,
  hexCount: 0,
  yieldPerHour: { m: 0, g: 0 },
});

/** Empty breakdown — exported so UI can render a zero row without branching. */
export const EMPTY_POWER: PowerBreakdown = Object.freeze(zeroPower());

function seal(power: PowerBreakdown): PowerBreakdown {
  power.unitPower = Math.round(power.unitPower);
  power.territoryPower = Math.round(power.territoryPower);
  power.total = power.unitPower + power.territoryPower;
  return power;
}

/**
 * Power breakdown for one commander.
 *
 * `unitPower` counts EVERY unit the player commands: units riding in their
 * armies AND units sitting in the reserve garrisons of the hexes they own
 * (GDD §5 — "an army carries up to 8 units; excess units stay in reserve at
 * owned hexes"). Reserves are still commanded strength, so they still count.
 */
export function powerOf(state: GameState, playerId: PlayerId): PowerBreakdown {
  const player = state.players[playerId];
  if (!player) return zeroPower();
  const power = zeroPower();

  for (const army of Object.values(state.armies)) {
    if (army.ownerId !== playerId) continue;
    for (const unit of army.units) power.unitPower += unitMineralValue(unit.type);
  }

  for (const hex of Object.values(state.world.hexes)) {
    if (hex.ownerId !== playerId) continue;

    power.hexCount++;
    const yieldOf = hexYieldPerHour(hex);
    power.yieldPerHour.m += yieldOf.m;
    power.yieldPerHour.g += yieldOf.g;

    for (const type of Object.keys(hex.reserves) as UnitType[]) {
      const count = hex.reserves[type] ?? 0;
      power.unitPower += unitMineralValue(type) * count;
    }
  }

  power.territoryPower = mineralEquivalent(power.yieldPerHour) * GUILD.powerYieldK;
  return seal(power);
}

/** Aggregate power for a whole guild — the sum of its members' breakdowns. */
export function guildPower(state: GameState, guildId: GuildId): PowerBreakdown {
  const guild = state.guilds[guildId];
  if (!guild) return zeroPower();
  const total = zeroPower();

  for (const memberId of guild.memberIds) {
    const p = powerOf(state, memberId);
    total.unitPower += p.unitPower;
    total.territoryPower += p.territoryPower;
    total.hexCount += p.hexCount;
    total.yieldPerHour.m += p.yieldPerHour.m;
    total.yieldPerHour.g += p.yieldPerHour.g;
  }
  return seal(total);
}

// ─────────────────────────────────────────────────────────────────────────────
// Roster (GDD §9.2)
// ─────────────────────────────────────────────────────────────────────────────

/** One army on a member's roster row: where it is and what it is doing. */
export interface RosterArmy {
  armyId: ArmyId;
  name: string;
  hexId: HexId;
  unitCount: number;
  moving: boolean;
  arrivesAt?: number;
  besieging: boolean;
}

/** Everything the roster screen shows for one commander. */
export interface RosterRow {
  playerId: PlayerId;
  name: string;
  role: GuildRole;
  isDiplomat: boolean;
  online: boolean;
  lastSeen: number;
  hue: number;
  bot: boolean;
  power: PowerBreakdown;
  hexCount: number;
  /** Stockpiles are visible to guildmates (GDD §9.2). */
  minerals: number;
  gas: number;
  armyCount: number;
  /** Units in armies + units in reserve on owned hexes. */
  unitCount: number;
  reserveCount: number;
  armies: RosterArmy[];
  /** Hexes the member's armies currently stand on, for the map overlay. */
  armyPositions: HexId[];
}

/**
 * Member roster, strongest first (ties broken by name so the order is stable).
 * Every field the GDD asks for: power (split), owned hex count, stockpiles,
 * online status, armies and their positions.
 */
export function rosterOf(state: GameState, guildId: GuildId): RosterRow[] {
  const guild = state.guilds[guildId];
  if (!guild) return [];

  const rows: RosterRow[] = [];

  for (const memberId of guild.memberIds) {
    const player = state.players[memberId];
    if (!player) continue;

    const power = powerOf(state, memberId);
    const armies: RosterArmy[] = [];
    let unitCount = 0;

    for (const army of Object.values(state.armies)) {
      if (army.ownerId !== memberId) continue;
      unitCount += army.units.length;
      armies.push({
        armyId: army.id,
        name: army.name,
        hexId: army.hexId,
        unitCount: army.units.length,
        moving: army.path.length > 0,
        arrivesAt: army.arrivesAt,
        besieging: !!army.siege,
      });
    }
    armies.sort((a, b) => b.unitCount - a.unitCount || a.name.localeCompare(b.name));

    let reserveCount = 0;
    for (const hex of Object.values(state.world.hexes)) {
      if (hex.ownerId !== memberId) continue;
      for (const type of Object.keys(hex.reserves) as UnitType[]) {
        reserveCount += hex.reserves[type] ?? 0;
      }
    }

    rows.push({
      playerId: memberId,
      name: player.name,
      role: roleOf(state, memberId) ?? 'member',
      isDiplomat: guild.leaderId === memberId || guild.diplomats.includes(memberId),
      online: player.online,
      lastSeen: player.lastSeen,
      hue: player.hue,
      bot: player.bot,
      power,
      hexCount: power.hexCount,
      minerals: player.minerals,
      gas: player.gas,
      armyCount: armies.length,
      unitCount: unitCount + reserveCount,
      reserveCount,
      armies,
      armyPositions: armies.map((a) => a.hexId),
    });
  }

  rows.sort((a, b) => b.power.total - a.power.total || a.name.localeCompare(b.name));
  return rows;
}
